def isScramble(S1: str, S2: str) -> bool:
    n = len(S1)
    if n != len(S2):
        return False

    # Base case: if the strings are of length 1, they are scrambled if they are equal
    if n == 1:
        return S1 == S2

    # Check if the sorted characters of both strings are the same
    if sorted(S1) != sorted(S2):
        return False

